<?php
declare(strict_types=1);require_once __DIR__.'/../app/bootstrap.php';$db=Database::pdo();$days=Env::int('PENDING_RECHECK_DAYS',7);$st=$db->prepare("SELECT t.*,b.* FROM transactions t JOIN bank_profiles b ON b.id=t.bank_id WHERE t.status='PENDING' AND t.created_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL ? DAY) LIMIT 1000");$st->bindValue(1,$days,PDO::PARAM_INT);$st->execute();$rows=$st->fetchAll();$expired=0;foreach($rows as $r){$bank=BankService::get($db,(int)$r['bank_id']);if(!$bank)continue;[$ok]=ReconciliationService::apply($db,$bank,['reference'=>$r['reference'],'status'=>'EXPIRED','raw'=>['rule'=>$days.'-day reconciliation window']],'SYSTEM');if($ok)$expired++;}$sms=SmsService::processOutbox($db);echo json_encode(['expired'=>$expired,'sms'=>$sms],JSON_UNESCAPED_SLASHES).PHP_EOL;
